// Deal Calculator workflow overlay — Sale context + GỬI ADMIN XỬ LÝ + Admin import/lock snapshot
(function(){
  'use strict';
  const API_URL='https://script.google.com/macros/s/AKfycbw32BGSXwFVOpRCknx5hn8-k2m5ZXox26_y2mnZKVWL0JKHCv_Qtly5JiY0FS9e87kU/exec';
  const SESSION_KEY='sunbot_sale_v27_session';
  const CONTEXT_KEY='sunbot_calculator_school_context';
  const IMPORT_KEY='sunbot_calculator_import_snapshot';
  const pending=new Map();let adminPack=null;
  function context(){try{return JSON.parse(localStorage.getItem(CONTEXT_KEY)||'null')}catch(e){return null}}
  function notify(msg,bad){if(typeof showToast==='function')showToast(msg);else if(bad)alert(msg);}
  function reqId(){return 'r'+Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
  window.addEventListener('message',function(ev){if(!(ev.origin==='https://script.google.com'||ev.origin.endsWith('.googleusercontent.com')))return;const d=ev.data||{};if(d.type!=='sunbot-pages-response'||!d.requestId)return;const p=pending.get(d.requestId);if(!p)return;pending.delete(d.requestId);p.frame.remove();clearTimeout(p.timer);d.ok?p.resolve(d.result):p.reject(new Error(d.error||'Có lỗi xảy ra.'));});
  function bridgeMode(mode,subaction,payload){return new Promise(function(resolve,reject){const id=reqId(),frame=document.createElement('iframe');frame.name='calc_bridge_'+id;frame.style.display='none';document.body.appendChild(frame);const timer=setTimeout(function(){pending.delete(id);frame.remove();reject(new Error('Kết nối máy chủ quá thời gian.'));},25000);pending.set(id,{resolve,reject,frame,timer});const form=document.createElement('form');form.method='POST';form.action=API_URL;form.target=frame.name;form.style.display='none';const fields={action:'pagesBridge',request_id:id,mode:mode,subaction:subaction,token:localStorage.getItem(SESSION_KEY)||'',payload:JSON.stringify(payload||{})};Object.entries(fields).forEach(function(kv){const i=document.createElement('input');i.type='hidden';i.name=kv[0];i.value=kv[1];form.appendChild(i)});document.body.appendChild(form);form.submit();form.remove();});}
  function captureControls(){const out={};document.querySelectorAll('input[id],select[id],textarea[id]').forEach(function(e){if(e.type==='checkbox'||e.type==='radio')out[e.id]={value:e.value,checked:!!e.checked,type:e.type};else out[e.id]={value:e.value,type:e.type||e.tagName.toLowerCase()};});return out;}
  function captureActiveButtons(){const out=[];document.querySelectorAll('button.active').forEach(function(b){const d={text:String(b.textContent||'').trim()};Object.keys(b.dataset||{}).forEach(function(k){d[k]=b.dataset[k]});out.push(d);});return out;}
  function captureGlobals(){const g={};try{g.mode=typeof mode!=='undefined'?mode:null}catch(e){}try{g.programs=typeof programs!=='undefined'?programs:null}catch(e){}try{g.term=typeof term!=='undefined'?term:null}catch(e){}try{g.launch=typeof launch!=='undefined'?launch:null}catch(e){}try{g.service=typeof service!=='undefined'?service:null}catch(e){}try{g.extra=typeof extra!=='undefined'?extra:null}catch(e){}try{g.rolloutFunding=typeof rolloutFunding!=='undefined'?rolloutFunding:null}catch(e){}return g;}
  function captureSnapshot(){const c=context()||(adminPack&&adminPack.snapshot&&adminPack.snapshot.school)||null;return {schema_version:'calculator-snapshot-2026.09.12-v1',captured_at:new Date().toISOString(),school:c||null,controls:captureControls(),active_buttons:captureActiveButtons(),globals:captureGlobals(),url:location.href};}
  async function sendAdmin(btn){const c=context(),token=localStorage.getItem(SESSION_KEY)||'';if(!c||!c.school_id)return notify('Hãy mở Máy tính từ hồ sơ một trường trước khi gửi Admin.',true);if(!token)return notify('Phiên Sale chưa có. Hãy mở Máy tính từ Sale Workspace.',true);btn.disabled=true;const old=btn.textContent;btn.textContent='ĐANG GỬI…';try{const summary=typeof planText==='function'?planText():'';const r=await bridgeMode('v2Proposal','submit',{school_id:c.school_id,calculator_version:'deal-calculator-20260912',snapshot:captureSnapshot(),summary_text:summary});notify('Đã gửi Admin xử lý · '+r.proposal_snapshot_id);try{window.parent.postMessage({type:'sunbot-proposal-sent',proposal_snapshot_id:r.proposal_snapshot_id,school_id:c.school_id},'https://sunbotvietnam.github.io')}catch(e){}}catch(e){notify(e.message,true)}finally{btn.disabled=false;btn.textContent=old}}
  async function lockCommercial(btn){if(!adminPack||!adminPack.proposal_snapshot_id)return notify('Không có Proposal Snapshot nguồn để khóa.',true);if(!confirm('Khóa phương án hiện tại thành Commercial Snapshot chính thức? Bản đã khóa sẽ không bị sửa ngược.'))return;btn.disabled=true;const old=btn.textContent;btn.textContent='ĐANG KHÓA…';try{const summary=typeof planText==='function'?planText():'';const r=await bridgeMode('v2Commercial','lock',{proposal_snapshot_id:adminPack.proposal_snapshot_id,calculator_version:'deal-calculator-20260912',pricebook_version:'2026.09.12-v5',snapshot:captureSnapshot(),summary_text:summary});notify('Đã khóa phương án · '+r.commercial_snapshot_id);btn.textContent='ĐÃ KHÓA · '+r.commercial_snapshot_id;btn.disabled=true;try{window.parent.postMessage({type:'sunbot-commercial-locked',commercial_snapshot_id:r.commercial_snapshot_id,proposal_snapshot_id:r.proposal_snapshot_id,school_id:r.school_id},'https://sunbotvietnam.github.io')}catch(e){}}catch(e){notify(e.message,true);btn.disabled=false;btn.textContent=old}}
  function restoreButtons(snapshot){(snapshot.active_buttons||[]).forEach(function(saved){const keys=Object.keys(saved).filter(function(k){return k!=='text'});let target=null;document.querySelectorAll('button').forEach(function(b){if(target)return;const ok=keys.length&&keys.every(function(k){return String(b.dataset&&b.dataset[k]||'')===String(saved[k]||'')});if(ok)target=b;});if(target&&!target.classList.contains('active'))target.click();});}
  function restoreControls(snapshot){Object.keys(snapshot.controls||{}).forEach(function(id){const e=document.getElementById(id),v=snapshot.controls[id];if(!e||!v)return;if(e.type==='checkbox'||e.type==='radio')e.checked=!!v.checked;else e.value=v.value;e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));});}
  function importSnapshot(){try{adminPack=JSON.parse(localStorage.getItem(IMPORT_KEY)||'null')}catch(e){adminPack=null}if(!adminPack||!adminPack.snapshot)return false;localStorage.removeItem(IMPORT_KEY);const snap=adminPack.snapshot;setTimeout(function(){restoreButtons(snap);restoreControls(snap);const b=document.createElement('div');b.id='adminImportContext';b.style.cssText='margin:10px auto 0;max-width:1180px;padding:10px 14px;border:1px solid #99e0d8;background:#ecfdfb;border-radius:10px;font:600 13px Arial;color:#0f766e';b.textContent='Admin đang xử lý '+(adminPack.proposal_snapshot_id||'')+' · '+((snap.school&&snap.school.school_name)||adminPack.school_name||'Trường')+'. Có thể hiệu chỉnh; snapshot Sale gốc không bị sửa.';const first=document.querySelector('.hero')||document.body.firstElementChild;if(first&&first.parentNode)first.parentNode.insertBefore(b,first);notify('Đã nạp phương án Sale gửi.');installAdminLockButton();},180);return true;}
  function installAdminLockButton(){if(!adminPack||document.getElementById('lockCommercialSnapshot'))return;const copy=document.getElementById('copyPlan');const btn=document.createElement('button');btn.id='lockCommercialSnapshot';btn.className='softBtn';btn.textContent='KHÓA PHƯƠNG ÁN';btn.style.background='#0f766e';btn.style.color='#fff';btn.style.borderColor='#0f766e';btn.onclick=function(){lockCommercial(btn)};if(copy)copy.insertAdjacentElement('afterend',btn);else document.body.insertBefore(btn,document.body.firstChild);}
  function install(){const imported=importSnapshot();const copy=document.getElementById('copyPlan');if(copy)copy.textContent='TÓM TẮT PHƯƠNG ÁN';if(imported)return;if(document.getElementById('sendAdminProposal'))return;const c=context(),token=localStorage.getItem(SESSION_KEY)||'';if(!c||!token)return;const btn=document.createElement('button');btn.id='sendAdminProposal';btn.className='softBtn';btn.textContent='GỬI ADMIN XỬ LÝ';btn.style.background='#f47c20';btn.style.color='#fff';btn.style.borderColor='#f47c20';btn.onclick=function(){sendAdmin(btn)};if(copy)copy.insertAdjacentElement('afterend',btn);else document.body.insertBefore(btn,document.body.firstChild);const banner=document.createElement('div');banner.id='saleSchoolContext';banner.style.cssText='margin:10px auto 0;max-width:1180px;padding:10px 14px;border:1px solid #fed7aa;background:#fff7ed;border-radius:10px;font:600 13px Arial;color:#9a3412';banner.textContent='Đang tính cho: '+c.school_name+' · Snapshot gửi Admin sẽ gắn với đúng hồ sơ trường này.';const first=document.querySelector('.hero')||document.body.firstElementChild;if(first&&first.parentNode)first.parentNode.insertBefore(banner,first);}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(install,80)});else setTimeout(install,80);
})();
